export const BANCO: PreguntaDificil[] = FILAS.map(([id, pregunta, correcta, falsas, explica, ref]) => ({ id, pregunta, correcta, falsas, explica, ref }));

const POR_ID = new Map(BANCO.map((q) => [q.id, q]));

export function preguntaPorId(id: string): PreguntaDificil | undefined {
  return POR_ID.get(id);
}
